// Configure search window & optional keyword filter (zero API keys required)
const daysBack = 14;
const since = new Date(Date.now() - daysBack * 86400000).toISOString().slice(0, 19) + 'Z';
const limit = 25;
const keywordFilter = ''; // Optional substring filter e.g. 'software' or 'cloud'
const requestUrl = `https://www.contractsfinder.service.gov.uk/Published/Notices/OCDS/Search?publishedFrom=${encodeURIComponent(since)}&stages=tender,award&limit=${limit}`;

return [{
  json: {
    since,
    limit,
    keywordFilter,
    requestUrl,
  },
}];

// Parse official Contracts Finder OCDS releases into B2B buyer leads
const cfg = $('Configure Tender Query').first().json;
const kw = String(cfg.keywordFilter || '').trim().toLowerCase();
const payload = $input.first().json || {};
const releases = Array.isArray(payload.releases) ? payload.releases : [];
const uuidRe = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

const out = [];
for (const rel of releases) {
  const tender = rel.tender || {};
  const title = String(tender.title || '').trim();
  const description = String(tender.description || '').trim();
  if (kw && !title.toLowerCase().includes(kw) && !description.toLowerCase().includes(kw)) {
    continue;
  }
  const parties = Array.isArray(rel.parties) ? rel.parties : [];
  const buyer = parties.find((p) => Array.isArray(p.roles) && (p.roles.includes('buyer') || p.roles.includes('procuringEntity'))) || parties[0] || {};
  const contact = buyer.contactPoint || {};
  const addr = buyer.address || {};
  const val = tender.value || tender.minValue || {};
  const rawId = String(rel.id || '');
  const uuidCandidate = rawId.includes('-') ? rawId.replace(/-[^-]+$/, '') : rawId;
  const noticeUrl = uuidRe.test(uuidCandidate)
    ? `https://www.contractsfinder.service.gov.uk/Notice/${uuidCandidate}`
    : 'https://www.contractsfinder.service.gov.uk/';

  const valueGbp = typeof val.amount === 'number' ? val.amount : null;
  const deadline = String((tender.tenderPeriod || {}).endDate || '').slice(0, 10) || null;
  const buyerName = String(buyer.name || (rel.buyer || {}).name || '').trim();
  const buyerEmail = contact.email ? String(contact.email).trim() : null;

  out.push({
    json: {
      ocid: rel.ocid || null,
      title,
      buyerName,
      buyerContact: contact.name ? String(contact.name).trim() : null,
      buyerEmail,
      buyerPhone: contact.telephone ? String(contact.telephone).trim() : null,
      locality: addr.locality || addr.region || null,
      valueGbp,
      currency: val.currency || 'GBP',
      deadline,
      stage: tender.status || 'published',
      publishedDate: String(rel.date || '').slice(0, 10),
      noticeUrl,
      agentSummary: `${title} | Buyer: ${buyerName}${buyerEmail ? ' (' + buyerEmail + ')' : ''}${valueGbp ? ' | £' + valueGbp.toLocaleString('en-US') : ''}${deadline ? ' | Due ' + deadline : ''}`,
    },
  });
}

return out.length ? out : [{ json: { status: 'no_matching_tenders', since: cfg.since } }];
